//! YAML encoding.
//!
//! The API kinds are protobuf messages, so the protobuf JSON mapping (as
//! generated by pbjson) is the single source of truth for their wire names
//! (lowerCamelCase), timestamp format (RFC 3339), and which fields are omitted
//! when unset. YAML is bridged through it: manifests are decoded generically,
//! converted to JSON, and then decoded strictly, so unknown or misspelled fields
//! are rejected. Output follows the proto field order instead of being sorted.
//!
//! A few legacy manifest shapes are still accepted. They are rewritten on the
//! generic document before strict decoding by the per-kind normalizers below.

use std::sync::LazyLock;

use prost_reflect::{DescriptorPool, Kind, MessageDescriptor};
use serde::{Serialize, de::DeserializeOwned};
use serde_json::{Map, Value};

use crate::v1alpha1::{FILE_DESCRIPTOR_SET, Gateway, Model, Task, Workspace};

#[derive(Debug, thiserror::Error)]
pub enum YamlError {
    #[error("parsing yaml: {0}")]
    Yaml(#[from] serde_yaml_ng::Error),
    #[error("{0}")]
    Schema(#[from] serde_json::Error),
}

/// An API kind that can be read from and written to a YAML manifest.
pub trait Manifest: Serialize + DeserializeOwned {
    /// The fully qualified protobuf message name, such as `ax.v1alpha1.Task`.
    const MESSAGE: &'static str;

    /// Rewrites legacy shapes of the generically decoded document in place so
    /// they match the current schema before strict decoding.
    fn normalize(_doc: &mut Map<String, Value>) {}
}

impl Manifest for Task {
    const MESSAGE: &'static str = "ax.v1alpha1.Task";
}

impl Manifest for Workspace {
    const MESSAGE: &'static str = "ax.v1alpha1.Workspace";

    /// Accepts spec.mcp written as a bare list of servers.
    fn normalize(doc: &mut Map<String, Value>) {
        if let Some(Value::Object(spec)) = doc.get_mut("spec")
            && let Some(mcp) = spec.get_mut("mcp")
            && mcp.is_array()
        {
            let servers = mcp.take();
            *mcp = serde_json::json!({ "servers": servers });
        }
    }
}

impl Manifest for Gateway {
    const MESSAGE: &'static str = "ax.v1alpha1.Gateway";
}

impl Manifest for Model {
    const MESSAGE: &'static str = "ax.v1alpha1.Model";

    /// Accepts older spellings of the secret reference: spec.secretKeyRef,
    /// spec.apiKey.secretKeyRef, and a bare string meaning the secret name and
    /// key are the same.
    fn normalize(doc: &mut Map<String, Value>) {
        let Some(Value::Object(spec)) = doc.get_mut("spec") else {
            return;
        };
        let legacy_ref = spec.remove("secretKeyRef");
        let api_key_ref = match spec.remove("apiKey") {
            Some(Value::Object(mut api_key)) => api_key.remove("secretKeyRef"),
            _ => None,
        };
        if !spec.contains_key("secretKey")
            && let Some(r) = legacy_ref.or(api_key_ref)
        {
            spec.insert("secretKey".into(), r);
        }
        if let Some(Value::String(s)) = spec.get("secretKey") {
            let s = s.clone();
            spec.insert(
                "secretKey".into(),
                serde_json::json!({ "name": s, "key": s }),
            );
        }
    }
}

/// Decodes a manifest strictly: unknown or misspelled fields are errors.
pub fn from_yaml<T: Manifest>(src: &str) -> Result<T, YamlError> {
    Ok(serde_json::from_value(to_document::<T>(src)?)?)
}

/// Decodes a manifest like [`from_yaml`] but ignores fields it doesn't know.
/// Runners use it for the specs the control plane passes them, so a runner
/// image keeps working when a newer control plane adds fields it doesn't use.
pub fn from_yaml_lenient<T: Manifest>(src: &str) -> Result<T, YamlError> {
    let mut doc = to_document::<T>(src)?;
    prune_unknown(&mut doc, &descriptor::<T>());
    Ok(serde_json::from_value(doc)?)
}

/// Encodes a resource as YAML, with fields in proto order and unset fields
/// omitted.
pub fn to_yaml<T: Manifest>(m: &T) -> Result<String, YamlError> {
    Ok(serde_yaml_ng::to_string(&to_json(m)?)?)
}

/// Encodes a resource in the protobuf JSON mapping, as protojson would.
pub fn to_json<T: Manifest>(m: &T) -> Result<Value, YamlError> {
    let mut v = serde_json::to_value(m)?;
    canonicalize_timestamps(&mut v, &descriptor::<T>());
    Ok(v)
}

/// Decodes a resource from the protobuf JSON mapping, ignoring fields it
/// doesn't know, as stores do for records a newer server may have written.
/// Legacy shapes are not rewritten: stored records are always current.
pub fn from_json_lenient<T: Manifest>(mut doc: Value) -> Result<T, YamlError> {
    prune_unknown(&mut doc, &descriptor::<T>());
    Ok(serde_json::from_value(doc)?)
}

fn descriptor<T: Manifest>() -> MessageDescriptor {
    POOL.get_message_by_name(T::MESSAGE)
        .unwrap_or_else(|| panic!("{} is not in the AX descriptor set", T::MESSAGE))
}

/// Rewrites Timestamp fields from the `+00:00` offset pbjson writes to the `Z`
/// suffix protojson writes, so both implementations produce the same text.
fn canonicalize_timestamps(value: &mut Value, desc: &MessageDescriptor) {
    let Value::Object(obj) = value else { return };
    for (key, v) in obj.iter_mut() {
        let Some(field) = desc.get_field_by_json_name(key) else {
            continue;
        };
        let Kind::Message(child) = field.kind() else {
            continue;
        };
        let values: Vec<&mut Value> = match v {
            Value::Array(items) => items.iter_mut().collect(),
            _ => vec![v],
        };
        for v in values {
            if child.full_name() == "google.protobuf.Timestamp" {
                if let Value::String(s) = v
                    && let Ok(t) = chrono::DateTime::parse_from_rfc3339(s)
                {
                    *s = t
                        .to_utc()
                        .to_rfc3339_opts(chrono::SecondsFormat::AutoSi, true);
                }
            } else if !child.full_name().starts_with("google.protobuf.") {
                canonicalize_timestamps(v, &child);
            }
        }
    }
}

fn to_document<T: Manifest>(src: &str) -> Result<Value, YamlError> {
    let mut doc: Value = serde_yaml_ng::from_str(src)?;
    if doc.is_null() {
        doc = Value::Object(Map::new());
    }
    if let Value::Object(obj) = &mut doc {
        T::normalize(obj);
    }
    Ok(doc)
}

static POOL: LazyLock<DescriptorPool> = LazyLock::new(|| {
    DescriptorPool::decode(FILE_DESCRIPTOR_SET).expect("the AX descriptor set is valid")
});

/// Drops every object key that is not a field of `desc`, recursing into
/// message fields. Well-known types such as Struct and Timestamp are left
/// alone: their contents are not schema fields.
fn prune_unknown(value: &mut Value, desc: &MessageDescriptor) {
    if desc.full_name().starts_with("google.protobuf.") {
        return;
    }
    let Value::Object(obj) = value else { return };
    obj.retain(|key, _| {
        desc.get_field_by_json_name(key)
            .or_else(|| desc.get_field_by_name(key))
            .is_some()
    });
    for (key, v) in obj.iter_mut() {
        let field = desc
            .get_field_by_json_name(key)
            .or_else(|| desc.get_field_by_name(key))
            .unwrap();
        if let Kind::Message(child) = field.kind() {
            match v {
                Value::Array(items) => items
                    .iter_mut()
                    .for_each(|item| prune_unknown(item, &child)),
                _ => prune_unknown(v, &child),
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::v1alpha1::*;
    use crate::{API_VERSION, KIND_MODEL, KIND_TASK};
    use serde_json::json;

    fn ts(s: &str) -> pbjson_types::Timestamp {
        serde_json::from_value(json!(s)).unwrap()
    }

    fn st(v: Value) -> pbjson_types::Struct {
        serde_json::from_value(v).unwrap()
    }

    /// A Task with every field populated so round trips exercise the whole
    /// schema, including timestamps and status.
    fn full_task() -> Task {
        Task {
            api_version: API_VERSION.into(),
            kind: KIND_TASK.into(),
            metadata: Some(ObjectMeta {
                name: "full".into(),
                atespace: "default".into(),
                create_time: Some(ts("2026-09-19T12:00:00Z")),
            }),
            spec: Some(TaskSpec {
                image: "example.com/img:1".into(),
                command: vec!["sh".into(), "-c".into(), "true".into()],
                env: vec![EnvVar {
                    name: "A".into(),
                    value: "1".into(),
                }],
                resources: Some(ResourcesSpec {
                    requests: Some(ResourceList {
                        cpu: "500m".into(),
                        memory: "1Gi".into(),
                    }),
                    limits: None,
                }),
                workspace: Some(WorkspaceRef {
                    name: "ws".into(),
                    path: "/workspace".into(),
                }),
                debug: true,
                config: None,
                gateway: Some(GatewayRef { name: "gw".into() }),
            }),
            status: Some(TaskStatus {
                phase: "Running".into(),
                id: "id-1".into(),
                actor: "actor-1".into(),
                worker_ip: "10.0.0.5:80".into(),
                conditions: vec![Condition {
                    r#type: "Ready".into(),
                    status: "True".into(),
                    reason: "TaskRunning".into(),
                    message: "ok".into(),
                    update_time: Some(ts("2026-09-19T12:05:00Z")),
                }],
            }),
        }
    }

    fn round_trip<T: Manifest + PartialEq + std::fmt::Debug>(want: &T) -> String {
        let out = to_yaml(want).unwrap();
        let got: T = from_yaml(&out).unwrap_or_else(|e| panic!("{e}\n{out}"));
        assert_eq!(&got, want, "yaml round trip changed the resource\n{out}");
        out
    }

    #[test]
    fn task_round_trip_and_shape() {
        let out = round_trip(&full_task());
        for want in [
            "workerIP: 10.0.0.5:80",
            "updateTime: 2026-09-19T12:05:00Z",
            "createTime: 2026-09-19T12:00:00Z",
        ] {
            assert!(out.contains(want), "yaml missing {want}:\n{out}");
        }
        // Top-level keys follow the proto definition, not alphabetical order.
        let positions: Vec<_> = [
            "apiVersion:",
            "\nkind:",
            "\nmetadata:",
            "\nspec:",
            "\nstatus:",
        ]
        .iter()
        .map(|k| out.find(k).unwrap_or_else(|| panic!("missing {k}:\n{out}")))
        .collect();
        assert!(positions.is_sorted(), "keys out of proto order:\n{out}");
        // Strings that look like other types are quoted so they read back as strings.
        assert!(
            out.contains("status: 'True'") || out.contains(r#"status: "True""#),
            "{out}"
        );
        // Unset fields are omitted rather than rendered as null.
        assert!(!out.contains("null"), "{out}");
    }

    #[test]
    fn strict_decoding_rejects_unknown_fields() {
        let err = from_yaml::<Task>("kind: Task\nspec:\n  imgae: typo\n")
            .unwrap_err()
            .to_string();
        assert!(err.contains("imgae"), "{err}");
    }

    #[test]
    fn workspace_mcp() {
        // Legacy: spec.mcp as a bare list of servers.
        let flat: Workspace = from_yaml(
            r#"
kind: Workspace
spec:
  mcp:
    - name: tool-1
      endpoint: "http://tool-1:8080"
    - name: tool-2
      command: "npx"
      args: ["-y", "@modelcontextprotocol/server"]
"#,
        )
        .unwrap();
        let servers = &flat.spec.unwrap().mcp.unwrap().servers;
        assert_eq!(servers.len(), 2);
        assert_eq!(servers[0].name, "tool-1");

        let ws: Workspace = from_yaml(
            r#"
kind: Workspace
spec:
  mcp:
    registries:
      - provider: google
        query: "mcp.tags:git"
      - provider: static
        servers:
          - name: git-tools
            endpoint: "http://git-mcp.default.svc.cluster.local:8080"
    servers:
      - name: tool-1
        endpoint: "http://tool-1:8080"
"#,
        )
        .unwrap();
        let mcp = ws.spec.unwrap().mcp.unwrap();
        assert_eq!(mcp.registries.len(), 2);
        assert_eq!(mcp.registries[0].query, "mcp.tags:git");
        assert_eq!(mcp.registries[1].provider, "static");
        assert_eq!(mcp.registries[1].servers[0].name, "git-tools");
        assert_eq!(mcp.servers.len(), 1);
    }

    #[test]
    fn workspace_round_trip() {
        let ws: Workspace = from_yaml(
            r##"
apiVersion: ax.io/v1alpha1
kind: Workspace
metadata:
  name: full-ws
  atespace: default
spec:
  git:
    - name: origin
      repo: "https://github.com/chalk/chalk.git"
      branch: "main"
      dir: chalk
      depth: 1
  files:
    - path: AGENTS.md
      content: "# Agent Guidelines\nFollow best practices."
  mcp:
    registries:
      - provider: google
        query: "mcp.tags:build"
  skills:
    registries:
      - provider: google
        query: "skills.tags:golang"
    path: "/.agents/skills"
"##,
        )
        .unwrap();
        let spec = ws.spec.as_ref().unwrap();
        assert_eq!(spec.git[0].depth, 1);
        assert_eq!(spec.skills.as_ref().unwrap().path, "/.agents/skills");
        assert_eq!(
            spec.files[0].content,
            "# Agent Guidelines\nFollow best practices."
        );
        round_trip(&ws);
    }

    #[test]
    fn model_secret_key_spellings() {
        for src in [
            "spec:\n  provider: google\n  secretKey:\n    name: the-secret\n    key: the-key\n",
            "spec:\n  provider: google\n  secretKeyRef:\n    name: the-secret\n    key: the-key\n",
            "spec:\n  provider: google\n  apiKey:\n    secretKeyRef:\n      name: the-secret\n      key: the-key\n",
        ] {
            let m: Model = from_yaml(&format!("kind: Model\n{src}")).unwrap();
            let key = m.spec.unwrap().secret_key.unwrap();
            assert_eq!(
                (key.name.as_str(), key.key.as_str()),
                ("the-secret", "the-key"),
                "{src}"
            );
        }
        let m: Model =
            from_yaml("kind: Model\nspec:\n  provider: google\n  secretKey: GEMINI_API_KEY\n")
                .unwrap();
        let key = m.spec.unwrap().secret_key.unwrap();
        assert_eq!(
            (key.name.as_str(), key.key.as_str()),
            ("GEMINI_API_KEY", "GEMINI_API_KEY")
        );
    }

    #[test]
    fn model_round_trip() {
        let want = Model {
            api_version: API_VERSION.into(),
            kind: KIND_MODEL.into(),
            metadata: Some(ObjectMeta {
                name: "m".into(),
                atespace: "default".into(),
                create_time: None,
            }),
            spec: Some(ModelSpec {
                provider: "google".into(),
                model: "gemini-3.8-flash".into(),
                secret_key: Some(SecretKeyRef {
                    name: "gemini-api-secret".into(),
                    key: "GEMINI_API_KEY".into(),
                }),
                parameters: Some(st(json!({
                    "temperature": 0.2,
                    "maxOutputTokens": 4096,
                    "systemInstruction": "be brief",
                    "stopSequences": ["END"],
                }))),
            }),
        };
        let out = round_trip(&want);
        for s in ["temperature: 0.2", "maxOutputTokens: 4096", "- END"] {
            assert!(
                out.contains(s),
                "expected {s:?} in parameters output:\n{out}"
            );
        }
    }

    const CONFIG_TASK_YAML: &str = r#"
apiVersion: ax.io/v1alpha1
kind: Task
metadata:
  name: swe-bench-shard-07
spec:
  image: us-docker.pkg.dev/acme/evals/harness:2026.10
  command: ["python3", "-m", "harness.run"]
  config:
    suite: swe_bench_verified
    shard: { index: 7, total: 32 }
    models:
      - provider: google
        model: gemini-3.8-flash
      - provider: google
        model: gemini-3.8-pro
    limits:
      per_case_timeout: 15m
      max_cost_usd: 25.5
    report:
      bucket: gs://acme-evals/results/
      dry_run: true
      since: "2026-10-01T00:00:00Z"
      version: "1"
      owner: null
"#;

    #[test]
    fn task_config() {
        let task: Task = from_yaml(CONFIG_TASK_YAML).unwrap();
        let want = st(json!({
            "suite": "swe_bench_verified",
            "shard": {"index": 7.0, "total": 32.0},
            "models": [
                {"provider": "google", "model": "gemini-3.8-flash"},
                {"provider": "google", "model": "gemini-3.8-pro"},
            ],
            "limits": {"per_case_timeout": "15m", "max_cost_usd": 25.5},
            "report": {
                "bucket": "gs://acme-evals/results/",
                "dry_run": true,
                "since": "2026-10-01T00:00:00Z",
                "version": "1",
                "owner": null,
            },
        }));
        assert_eq!(task.spec.as_ref().unwrap().config.as_ref(), Some(&want));

        // The config survives the YAML round trip the controller performs when
        // it builds AX_TASK_YAML, and runners decoding it leniently see it
        // unchanged.
        let out = round_trip(&task);
        let lenient: Task = from_yaml_lenient(&out).unwrap();
        assert_eq!(lenient, task, "lenient decoding changed the task\n{out}");
    }

    #[test]
    fn task_config_must_be_object() {
        for config in ["[1, 2]", "hello", "3"] {
            assert!(
                from_yaml::<Task>(&format!("kind: Task\nspec:\n  config: {config}\n")).is_err(),
                "{config}"
            );
        }
    }

    #[test]
    fn task_workspace_binding() {
        let task: Task = from_yaml(
            "apiVersion: ax.io/v1alpha1\nkind: Task\nmetadata:\n  name: single\nspec:\n  workspace:\n    name: code\n    path: /opt/code\n",
        )
        .unwrap();
        let r = task.spec.as_ref().unwrap().workspace.as_ref().unwrap();
        assert_eq!((r.name.as_str(), r.path.as_str()), ("code", "/opt/code"));
        let out = round_trip(&task);
        assert!(
            out.contains("workspace:") && !out.contains("workspaces:"),
            "{out}"
        );

        // The earlier spec.workspaces list is no longer part of the schema.
        assert!(from_yaml::<Task>("kind: Task\nspec:\n  workspaces:\n    - name: code\n").is_err());
    }

    #[test]
    fn gateway_round_trip() {
        let gw: Gateway = from_yaml(
            r#"
apiVersion: ax.io/v1alpha1
kind: Gateway
metadata:
  name: review-bot-gw
  atespace: default
spec:
  egress:
    - https:
        hostnames: ["api.anthropic.com"]
        effects:
          replaceHeaders:
            - header: x-api-key
              credentialUri: "ate-secret://k8s.io/default/default/anthropic-creds/api-key"
    - https:
        hostnames: ["api.github.com"]
        effects:
          replaceHeaders:
            - header: Authorization
              prefix: "Bearer "
              actorJwt:
                audiences: ["https://api.github.com"]
                expirationSeconds: 300
    - http:
        hostnames: ["mirror.example.com"]
        ports:
          numbers: [80, 8080]
    - tlsPassthrough:
        hostnames: ["db.example.com"]
        ports:
          all: {}
"#,
        )
        .unwrap();
        let egress = &gw.spec.as_ref().unwrap().egress;
        assert_eq!(egress.len(), 4);
        let headers = |i: usize| {
            &egress[i]
                .https
                .as_ref()
                .unwrap()
                .effects
                .as_ref()
                .unwrap()
                .replace_headers
        };
        assert_eq!(headers(0)[0].header, "x-api-key");
        assert_eq!(
            headers(0)[0].credential_uri,
            "ate-secret://k8s.io/default/default/anthropic-creds/api-key"
        );
        assert_eq!(headers(1)[0].prefix, "Bearer ");
        assert_eq!(
            headers(1)[0].actor_jwt.as_ref().unwrap().expiration_seconds,
            300
        );
        let ports = egress[2].http.as_ref().unwrap().ports.as_ref().unwrap();
        assert_eq!(ports.numbers, [80, 8080]);
        let ports = egress[3]
            .tls_passthrough
            .as_ref()
            .unwrap()
            .ports
            .as_ref()
            .unwrap();
        assert!(ports.all.is_some());
        let out = round_trip(&gw);
        assert!(out.contains("tlsPassthrough:"), "{out}");
    }

    #[test]
    fn task_gateway_binding() {
        let task: Task = from_yaml(
            "kind: Task\nmetadata:\n  name: bound\nspec:\n  gateway: {name: review-bot-gw}\n",
        )
        .unwrap();
        let r = task.spec.as_ref().unwrap().gateway.as_ref().unwrap();
        assert_eq!(r.name, "review-bot-gw");
        round_trip(&task);
    }

    #[test]
    fn lenient_ignores_unknown_fields() {
        let doc = "metadata:\n  name: t\n  atespace: default\n  futureMeta: x\nspec:\n  image: img\n  fieldFromTheFuture: 1\n  env:\n    - name: A\n      value: b\n      secret: true\n";
        assert!(
            from_yaml::<Task>(doc).is_err(),
            "strict decoding should reject an unknown field"
        );
        let task: Task = from_yaml_lenient(doc).unwrap();
        let spec = task.spec.unwrap();
        assert_eq!(spec.image, "img");
        assert_eq!(spec.env[0].value, "b");
    }

    #[test]
    fn lenient_normalizes_workspace() {
        let ws: Workspace =
            from_yaml_lenient("spec:\n  mcp:\n    - name: tool\n  extra: 1\n").unwrap();
        assert_eq!(ws.spec.unwrap().mcp.unwrap().servers[0].name, "tool");
    }

    #[test]
    fn empty_document_is_an_empty_resource() {
        assert_eq!(from_yaml::<Task>("").unwrap(), Task::default());
    }
}
